import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P02-2-basequestion/answer8.html","title":"08-章节测试八答案","lang":"zh-CN","frontmatter":{"title":"08-章节测试八答案","date":"2023-01-03T18:10:29.000Z","author":"AI悦创","isOriginal":true,"category":"Python 私教练习题【基础】","tag":["Python 基础练习题"],"icon":"python","sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"Python 中定义函数的关键字是_________________。 答案解析 正确答案：def 记忆性知识点 如果函数中没有 return 语句或者 return 语句不带任何返回值，那么该函数的返回值为_________________。 答案解析 正确答案：None 记忆性知识点 一般使用 4 个_________________或者 1 个_...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"08-章节测试八答案\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2023-01-03T18:10:29.000Z\\",\\"dateModified\\":\\"2025-06-01T12:54:28.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/column/Python-Programming-Course/P02-2-basequestion/answer8.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"08-章节测试八答案"}],["meta",{"property":"og:description","content":"Python 中定义函数的关键字是_________________。 答案解析 正确答案：def 记忆性知识点 如果函数中没有 return 语句或者 return 语句不带任何返回值，那么该函数的返回值为_________________。 答案解析 正确答案：None 记忆性知识点 一般使用 4 个_________________或者 1 个_..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-06-01T12:54:28.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:tag","content":"Python 基础练习题"}],["meta",{"property":"article:published_time","content":"2023-01-03T18:10:29.000Z"}],["meta",{"property":"article:modified_time","content":"2025-06-01T12:54:28.000Z"}]]},"git":{"createdTime":1672742330000,"updatedTime":1748782468000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":5,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":2}],"changelog":[{"hash":"f69810ac92e9a73ad46cbb9437d2c2cf6f2e4f67","time":1748782468000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新侧边栏和文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"bc507aa14ec6467356fdf51233112dea079ced6c","time":1745851817000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"移除所有章节答案文件中的推广信息和多余内容，简化文档结构"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"705557f8030ae4921c2d2f4cf0c4bd42c8b6436f","time":1672742330000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"}]},"readingTime":{"minutes":3.26,"words":978},"filePathRelative":"column/Python-Programming-Course/P02-2-basequestion/answer8.md","excerpt":"<ol>\\n<li>Python 中定义函数的关键字是_________________。</li>\\n</ol>\\n<div class=\\"hint-container tip\\">\\n<p class=\\"hint-container-title\\">答案解析</p>\\n<p>正确答案：def</p>\\n<p>记忆性知识点</p>\\n</div>\\n<ol start=\\"2\\">\\n<li>如果函数中没有 return 语句或者 return 语句不带任何返回值，那么该函数的返回值为_________________。</li>\\n</ol>\\n<div class=\\"hint-container tip\\">\\n<p class=\\"hint-container-title\\">答案解析</p>\\n<p>正确答案：None</p>\\n<p>记忆性知识点</p>\\n</div>","autoDesc":true}`),a={name:`answer8.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<ol><li>Python 中定义函数的关键字是_________________。</li></ol><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：def</p><p>记忆性知识点</p></div><ol start="2"><li>如果函数中没有 return 语句或者 return 语句不带任何返回值，那么该函数的返回值为_________________。</li></ol><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：None</p><p>记忆性知识点</p></div><ol start="3"><li>一般使用 4 个_________________或者 1 个_________________来表示函数的缩进。</li></ol><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：空格；Tab</p></div><ol start="4"><li>如果想要在 sublime text3 中将一段代码前都加上Tab键，可以将此段代码刷黑之后使用_________________快捷键。</li></ol><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：Tab</p></div><ol start="5"><li>函数体内的 pass 语句一般作为占位符或者创建占位程序，对此 python 不会执行任何操作。</li></ol><p>A. √</p><p>B. X</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：A 易错项：B</p></div><ol start="6"><li>Python 函数里的返回值只能返回一个值。</li></ol><p>A. √</p><p>B. X</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：B 易错项：A</p><p>python可以返回多个值，从本质来说是返回了一个包含多个值的元组。</p></div><ol start="7"><li>函数是通过函数名来进行调用的，但函数也可以当做参数被其他参数调用。</li></ol><p>A. √</p><p>B. X</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：A 易错项：B</p><p>记忆性知识点</p></div><ol start="8"><li>若一个 python 程序中命名了多个相同的函数名，则调用该函数时会执行最初定义的函数。</li></ol><p>A. √</p><p>B. X</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：B 易错项：A</p><p>如果 python 有两个函数的函数名与参数列表都相同。那么调用该函数时，哪个函数在后，则哪个被最终调用。</p></div><ol start="9"><li>函数名命名时应遵循变量的命名规则。</li></ol><p>A. √</p><p>B. X</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：A 易错项：B</p></div><ol start="10"><li>定义函数时，即使该函数不需要接收任何参数，也必须保留一对空的圆括号来表示这是一个函数。</li></ol><p>A. √</p><p>B. X</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：A 易错项：B</p></div><ol start="11"><li>定义 Python 函数时必须指定函数返回值类型。</li></ol><p>A. √</p><p>B. X</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：B 易错项：A</p><p>定义 Python 函数时可以不指定返回值及其类型。当不设置返回值时，默认返回 None。</p></div><ol start="12"><li>相同缩进位置的代码表示他们是同一个代码块。</li></ol><p>A. √</p><p>B. X</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：A 易错项：B</p></div><ol start="13"><li>自定义 Python 函数时可以在函数名称后的括号里不包含参数。</li></ol><p>A. √</p><p>B. X</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：A 易错项：B</p></div><ol start="14"><li>请选择以下代码的作用：<code>def sth(a,b,c):pass</code></li></ol><p>A. 定义了一个什么都没做的函数</p><p>B. 定义了一个空元组</p><p>C. 定义了一个空列表</p><p>D. 定义了一个空字符串</p><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：A 易错项：B</p></div><ol start="15"><li>此题无需在线作答，请在纸上作答后查看答案解析</li></ol><figure><img src="/assets/625104f63900facfaf9cb69d73d1c94b-CTPB_KqO.png" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>有程序如上图，则运行这个程序的结果是______。</p><div class="hint-container tip"><p class="hint-container-title">答案解析正确答案：1</p><p>定义了一个 fun 函数，函数功能为输出1然后返回2。</p><p>运行这个函数，得到的输出结果是1，这是因为函数里定义的输出为1，不管返回值是多少输出都为1，</p><p>如果想更了解 print 和 return 的差别，可以参考：<a href="https://blog.csdn.net/qq_33254766/article/details/117923418" target="_blank" rel="noopener noreferrer">https://blog.csdn.net/qq_33254766/article/details/117923418</a></p></div><ol start="16"><li>执行以下代码后，b的值为_______</li></ol><figure><img src="/assets/432b43c5a8b067909c0fc2077ae95573-Bqe_RYtp.png" alt="right" tabindex="0" loading="lazy"><figcaption>right</figcaption></figure><div class="hint-container tip"><p class="hint-container-title">答案解析</p><p>正确答案：25</p><p><code>sqr(4) </code> 的返回值为 16，<code>sqr(3)</code> 的返回值为 9. 两者相加为 25</p></div>`,57)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};